begin;
select no_plan();
create function pg_temp.eid(n integer) returns uuid language sql as $$select ('ef810000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.request() returns jsonb language sql as $$select jsonb_build_object('bindingId',pg_temp.eid(13),'videoId','abcdefghijk','sourceRunId',pg_temp.eid(20),'offset',0,'targetLanguage','zh-Hans')$$;
insert into auth.users(id,email) values(pg_temp.eid(1),'extension-translation@example.test');
insert into private.app_config(key,value) values('extension_oauth_client_id','extension-translation-fixture') on conflict(key) do update set value=excluded.value;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','extension-translation-fixture')::text,true);
select is(public.find_translation_run(pg_temp.request()),'{"run_id":null}'::jsonb,'configured extension can discover an exact caption page');
reset role;
insert into public.goals(id,owner_id,blueprint_id,title,position) select pg_temp.eid(10),owner_id,id,'Goal',0 from public.blueprints where owner_id=pg_temp.eid(1);
insert into public.stages(id,owner_id,goal_id,title,position) values(pg_temp.eid(11),pg_temp.eid(1),pg_temp.eid(10),'Stage',0);
insert into public.path_nodes(id,owner_id,stage_id,node_type,title,position) values(pg_temp.eid(12),pg_temp.eid(1),pg_temp.eid(11),'practice','Practice',0);
insert into public.resource_bindings(id,owner_id,node_id,kind,url,external_id,position)
 values(pg_temp.eid(13),pg_temp.eid(1),pg_temp.eid(12),'youtube_video','https://www.youtube.com/watch?v=abcdefghijk','abcdefghijk',0);
insert into private.resource_retention_policies values(pg_temp.eid(1),86400,'local-translation-find-fixture');
insert into public.resource_runs(id,owner_id,blueprint_id,blueprint_version,node_id,kind,preferences,learner_context,input_blueprint,result,status,expires_at)
 select pg_temp.eid(20),owner_id,id,version,pg_temp.eid(12),'discover','{}','{}',public.read_blueprint_snapshot_v2(owner_id),
 '{"status":"discovered","candidates":[{"video":{"videoId":"abcdefghijk","title":"Saved video"},"transcript":{"status":"ready","language":"en","segments":[{"text":"Original fixture text","offset":0,"duration":1000}]}}]}',
 'ready',clock_timestamp()+interval '120 seconds' from public.blueprints where owner_id=pg_temp.eid(1);
insert into private.translation_run_quotas values(pg_temp.eid(1),3);
create function pg_temp.begin_request(n integer) returns jsonb language sql as $$select pg_temp.request()||jsonb_build_object('runId',pg_temp.eid(n))$$;
create function pg_temp.skill() returns jsonb language sql as $$select jsonb_build_object('name','blueprint-translate-transcript','version','1.0.0','instructions','Translate fixture','sha256',encode(sha256(convert_to('Translate fixture','UTF8')),'hex'))$$;
set local role authenticated;
select is(public.begin_translation_run(pg_temp.begin_request(30))->>'status','queued','extension explicitly creates source-bound translation');
select is(public.read_translation_run(pg_temp.eid(30))->>'status','queued','extension reads its own queued receipt');
select is(public.cancel_translation_run(pg_temp.eid(30))->>'status','cancelled','extension can explicitly cancel');
select is(public.begin_translation_run(pg_temp.begin_request(30))->>'status','cancelled','same extension attempt recovers exact cancelled receipt');
select is(public.find_translation_run(pg_temp.request()),jsonb_build_object('run_id',pg_temp.eid(30)),'extension cloud recovery discovers existing terminal attempt');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated')::text,true);
select is(public.read_translation_run(pg_temp.eid(30))->>'status','cancelled','Web can recover the same extension-created attempt');
select is(public.begin_translation_run(pg_temp.begin_request(31))->>'status','queued','Web begin remains supported');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','extension-translation-fixture')::text,true);
select is(public.cancel_translation_run(pg_temp.eid(31))->>'status','cancelled','extension can cancel a same-owner Web attempt');
select throws_ok($$select public.begin_resource_run('{}')$$,'42501',null,'extension still cannot start resource Agent');
select throws_ok($$select public.begin_resource_adoption('{}')$$,'42501',null,'extension still cannot start resource adoption');
select throws_ok($$select public.begin_path_planning(pg_temp.eid(50),pg_temp.eid(51),0,0,current_date)$$,'42501',null,'extension still cannot start path Agent');
select throws_ok($$select public.create_goal_clarification(pg_temp.eid(50),pg_temp.eid(51),0)$$,'42501',null,'extension still cannot start clarification Agent');
select throws_ok($$select public.claim_translation_run(pg_temp.eid(1),pg_temp.eid(31),pg_temp.eid(90),pg_temp.skill(),'fixture-model')$$,'42501',null,'extension cannot claim worker lease');
select throws_ok($$select public.finish_translation_run(pg_temp.eid(1),pg_temp.eid(31),pg_temp.eid(90),'{}')$$,'42501',null,'extension cannot finish worker receipt');
select throws_ok($$select * from private.translation_runs$$,'42501',null,'extension cannot read raw body table');
select throws_ok($$select * from private.translation_run_quotas$$,'42501',null,'extension cannot access quota table');
select throws_ok($$select * from private.translation_run_leases$$,'42501',null,'extension cannot access lease table');
-- Claim fixtures exercise the public authorization seam, not a real OAuth grant.
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','null'::jsonb)::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot find: null');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot begin/replay: null');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot read: null');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot cancel: null');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','""'::jsonb)::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot find: empty');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot begin/replay: empty');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot read: empty');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot cancel: empty');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','"   "'::jsonb)::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot find: blank');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot begin/replay: blank');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot read: blank');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot cancel: blank');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','42'::jsonb)::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot find: number');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot begin/replay: number');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot read: number');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot cancel: number');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','true'::jsonb)::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot find: boolean');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot begin/replay: boolean');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot read: boolean');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot cancel: boolean');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','[]'::jsonb)::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot find: array');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot begin/replay: array');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot read: array');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot cancel: array');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','{}'::jsonb)::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot find: object');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot begin/replay: object');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot read: object');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot cancel: object');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','"unknown"'::jsonb)::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot find: unknown');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot begin/replay: unknown');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot read: unknown');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot cancel: unknown');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','" extension-translation-fixture"'::jsonb)::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot find: not normalized');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot begin/replay: not normalized');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot read: not normalized');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','invalid client cannot cancel: not normalized');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','extension-translation-fixture','is_anonymous',true)::text,true);
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','anonymous exact client denied');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','client_id','extension-translation-fixture')::text,true);
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501','TRANSLATION_FORBIDDEN','missing actor exact client denied');
reset role;
insert into auth.users(id,email) values(pg_temp.eid(2),'extension-translation-foreign@example.test');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(2),'role','authenticated','client_id','extension-translation-fixture')::text,true);
select is(public.find_translation_run(pg_temp.request()),'{"run_id":null}'::jsonb,'exact extension still cannot discover foreign history');
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'P0002','TRANSLATION_NOT_FOUND','exact extension cannot read foreign receipt');
select throws_ok($$select public.cancel_translation_run(pg_temp.eid(30))$$,'P0002','TRANSLATION_NOT_FOUND','exact extension cannot cancel foreign receipt');
select throws_ok($$select public.begin_translation_run(pg_temp.begin_request(30))$$,'P0002','TRANSLATION_NOT_FOUND','exact extension cannot replay foreign receipt');
reset role;
delete from private.app_config where key='extension_oauth_client_id';
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated','client_id','extension-translation-fixture')::text,true);
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','missing operator config defaults to Web only');
reset role;
insert into private.app_config values('extension_oauth_client_id','');
set local role authenticated;
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501','TRANSLATION_FORBIDDEN','empty operator config defaults to Web only');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.eid(1),'role','authenticated')::text,true);
select is(public.read_translation_run(pg_temp.eid(30))->>'status','cancelled','Web remains available with empty extension config');
reset role;
set local role anon;
select throws_ok($$select public.find_translation_run(pg_temp.request())$$,'42501',null,'anon execute grant remains absent');
reset role;
set local role service_role;
select throws_ok($$select public.read_translation_run(pg_temp.eid(30))$$,'42501',null,'service cannot act as translation caller');
reset role;
select ok((select not prosecdef and provolatile='s' and proconfig=array['search_path=""'] from pg_proc where oid='private.translation_actor()'::regprocedure),'translation actor remains a stable invoker with empty search path');
select * from finish();
rollback;
